-- 122: Original BrillaPrep WASSCE Commerce Detailed Syllabus beta questions, part 3.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_021', 'topic_was_commerce_5', 'subj_wassce_commerce', 'exam_wassce', 'Which bank service lets a business receive customer payments directly into its account?', 'multiple_choice', '["A. Electronic funds transfer","B. A warehouse warrant","C. A trade mark","D. A consignment note"]', 'A', 'Electronic transfers move value between accounts using authenticated payment systems and create transaction records for reconciliation. Therefore the correct answer is A: Electronic funds transfer.', 'hard', 1, 1, 90, 'st_was_commerce_5', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_022', 'topic_was_commerce_5', 'subj_wassce_commerce', 'exam_wassce', 'What is the main role of a central bank?', 'multiple_choice', '["A. Sell household goods at retail","B. Manage monetary policy and support stability of the banking system","C. Operate every private company","D. Provide only long-term warehouse space"]', 'B', 'A central bank issues or manages currency, implements monetary policy, holds reserves and performs regulatory or system-stability functions. Therefore the correct answer is B: Manage monetary policy and support stability of the banking system.', 'easy', 2, 2, 90, 'st_was_commerce_5', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_023', 'topic_was_commerce_5', 'subj_wassce_commerce', 'exam_wassce', 'Why might a profitable business still face a cash-flow problem?', 'multiple_choice', '["A. Profit and cash are always identical","B. All profitable sales are paid immediately","C. Cash may be tied up in stock or unpaid customer accounts","D. Expenses never fall due before revenue"]', 'C', 'Accounting profit can include credit sales, while wages and suppliers require cash. Timing differences can therefore create a liquidity shortage. Therefore the correct answer is C: Cash may be tied up in stock or unpaid customer accounts.', 'medium', 1, 1, 90, 'st_was_commerce_5', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_024', 'topic_was_commerce_5', 'subj_wassce_commerce', 'exam_wassce', 'Which source of finance is normally most suitable for a short temporary cash shortfall?', 'multiple_choice', '["A. Issuing permanent ordinary shares for one week","B. Selling all productive equipment","C. A thirty-year mortgage on stock","D. A bank overdraft within an agreed limit"]', 'D', 'An overdraft is flexible short-term bank credit charged on the amount used, though cost and repayment conditions must be assessed. Therefore the correct answer is D: A bank overdraft within an agreed limit.', 'hard', 2, 2, 90, 'st_was_commerce_5', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_025', 'topic_was_commerce_5', 'subj_wassce_commerce', 'exam_wassce', 'What is the purpose of a letter of credit in foreign trade?', 'multiple_choice', '["A. A bank conditionally undertakes payment when compliant documents are presented","B. It guarantees product quality after use","C. It removes all documentary requirements","D. It fixes the exchange rate forever"]', 'A', 'A documentary credit reduces payment risk by linking the bank’s undertaking to presentation of specified documents within stated terms. Therefore the correct answer is A: A bank conditionally undertakes payment when compliant documents are presented.', 'easy', 3, 3, 90, 'st_was_commerce_5', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_026', 'topic_was_commerce_6', 'subj_wassce_commerce', 'exam_wassce', 'Which insurance principle requires a person to stand to lose financially from the insured event?', 'multiple_choice', '["A. Contribution","B. Insurable interest","C. Subrogation","D. Arbitration"]', 'B', 'Insurable interest prevents insurance from becoming a wager by requiring a recognised financial or legal relationship with the subject matter. Therefore the correct answer is B: Insurable interest.', 'medium', 2, 2, 90, 'st_was_commerce_6', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_027', 'topic_was_commerce_6', 'subj_wassce_commerce', 'exam_wassce', 'What does the principle of indemnity seek to achieve?', 'multiple_choice', '["A. Allow the insured to profit from every loss","B. Pay every claim without evidence","C. Restore the insured financially to the approximate pre-loss position","D. Replace criminal law"]', 'C', 'For indemnity policies, compensation is linked to the actual covered loss and policy limits rather than creating a gain from misfortune. Therefore the correct answer is C: Restore the insured financially to the approximate pre-loss position.', 'hard', 1, 1, 90, 'st_was_commerce_6', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_028', 'topic_was_commerce_6', 'subj_wassce_commerce', 'exam_wassce', 'Which policy is most directly associated with goods transported by sea?', 'multiple_choice', '["A. Fidelity guarantee","B. Personal accident cover","C. Employer pension plan","D. Marine cargo insurance"]', 'D', 'Marine cargo insurance covers specified transit risks for goods moved by sea and related stages, subject to policy terms and exclusions. Therefore the correct answer is D: Marine cargo insurance.', 'easy', 2, 2, 90, 'st_was_commerce_6', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_029', 'topic_was_commerce_6', 'subj_wassce_commerce', 'exam_wassce', 'Why must an applicant disclose material facts to an insurer?', 'multiple_choice', '["A. They can affect whether the risk is accepted and on what terms","B. Disclosure guarantees that no claim will occur","C. Only the insurer has duties of honesty","D. Material facts never affect premiums"]', 'A', 'Insurance pricing and acceptance depend on relevant risk information, so concealing a material fact can undermine the contract or a claim. Therefore the correct answer is A: They can affect whether the risk is accepted and on what terms.', 'medium', 1, 1, 90, 'st_was_commerce_6', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_030', 'topic_was_commerce_6', 'subj_wassce_commerce', 'exam_wassce', 'What is reinsurance?', 'multiple_choice', '["A. A customer insuring the same phone twice for profit","B. Insurance purchased by an insurer to share part of its risk","C. Replacing an expired driving licence","D. A retailer returning goods to a wholesaler"]', 'B', 'Reinsurance spreads large or accumulated exposures across insurers and helps the original insurer manage capacity and solvency risk. Therefore the correct answer is B: Insurance purchased by an insurer to share part of its risk.', 'hard', 3, 3, 90, 'st_was_commerce_6', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published WAEC Ghana Commerce syllabus; not official WAEC examination material.', 'https://waecgh.org/wp-content/uploads/2024/07/COMMERCE.pdf', 0, 1 FROM questions WHERE id BETWEEN 'q_was_commerce_b001_021' AND 'q_was_commerce_b001_030';
